DROP TABLE IF EXISTS tecc_float_type_test CASCADE;
DROP TABLE IF EXISTS float_type_test CASCADE;
DROP DEK IF EXISTS dek_t1 CASCADE;
DROP KEK IF EXISTS kek_t1 CASCADE;
CREATE KEK kek_t1 WITH (KEY_STORE=localkms, KEY_PATH='/tmp/kek_t1.key');
CREATE DEK dek_t1 WITH VALUES (KEK=kek_t1);
CREATE TABLE tecc_float_type_test (id SERIAL PRIMARY KEY, numeric_col numeric_enc encrypted with (dek = dek_t1,support_algo='ope'), float4_col float4_enc encrypted with (dek = dek_t1,support_algo='ope'), float8_col float8_enc encrypted with (dek = dek_t1,support_algo='ope'));
CREATE TABLE float_type_test (id SERIAL PRIMARY KEY, numeric_col numeric, float4_col float4, float8_col float8);
INSERT INTO float_type_test (numeric_col, float4_col, float8_col) VALUES (0.0, 0.0, 0.0),(1.0, 1.0, 1.0),(10.0, 10.0, 10.0),(20.0, 20.0, 20.0),(30.0, 30.0, 30.0),(30.75, 30.75, 30.75),(40.0, 40.0, 40.0),(50.0, 50.0, 50.0),(60.0, 60.0, 60.0),(100.0, 100.0, 100.0),(-10.0, -10.0, -10.0),(-20.0, -20.0, -20.0),(-30.0, -30.0, -30.0),(NULL, NULL, NULL);
INSERT INTO tecc_float_type_test (numeric_col, float4_col, float8_col) VALUES (0.0, 0.0, 0.0),(1.0, 1.0, 1.0),(10.0, 10.0, 10.0),(20.0, 20.0, 20.0),(30.0, 30.0, 30.0),(30.75, 30.75, 30.75),(40.0, 40.0, 40.0),(50.0, 50.0, 50.0),(60.0, 60.0, 60.0),(100.0, 100.0, 100.0),(-10.0, -10.0, -10.0),(-20.0, -20.0, -20.0),(-30.0, -30.0, -30.0),(NULL, NULL, NULL);
SELECT id, numeric_col, float4_col, float8_col FROM float_type_test WHERE numeric_col > 0.0 AND numeric_col < 100.0 ORDER BY numeric_col;
SELECT id, numeric_col, float4_col, float8_col FROM tecc_float_type_test WHERE numeric_col > 0.0 AND numeric_col < 100.0 ORDER BY numeric_col;
SELECT id, numeric_col, float4_col, float8_col FROM float_type_test WHERE float4_col >= -20.0 AND float4_col <= 0.0 ORDER BY float4_col;
SELECT id, numeric_col, float4_col, float8_col FROM tecc_float_type_test WHERE float4_col >= -20.0 AND float4_col <= 0.0 ORDER BY float4_col;
SELECT id, numeric_col, float4_col, float8_col FROM float_type_test WHERE float8_col >= 10.0 AND float8_col <= 50.0 AND float8_col != 30.75 ORDER BY float8_col;
SELECT id, numeric_col, float4_col, float8_col FROM tecc_float_type_test WHERE float8_col >= 10.0 AND float8_col <= 50.0 AND float8_col != 30.75 ORDER BY float8_col;
DROP TABLE IF EXISTS tecc_float_type_test CASCADE;
DROP TABLE IF EXISTS float_type_test CASCADE;
DROP DEK IF EXISTS dek_t1 CASCADE;
DROP KEK IF EXISTS kek_t1 CASCADE;
